fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    let mut result = Vec::with_capacity(x.len());
    
    for &value in &x {
        result.push(value.ln() / std::f32::consts::LN_10);
    }
    
    result
}

fn main() {
    // Example usage
    let input = vec![1.0, 10.0, 100.0];
    let length = vec_len(&input);
    let log10_result = numpy_log10(input);
    
    println!("Length of input vector: {}", length);
    println!("Log10 of input vector: {:?}", log10_result);
}